{"component": {"id": 27378, "componentId": 13877, "authorUserId": "user_2vZexZytBe3Vo4fbfmzWgvCugbB", "name": "Command Menu with Global Search", "demoName": "Default", "description": "A searchable command palette dialog that lets users find chats, images, documents, and projects across an app, with type filters and recent/last-opened sections.", "previewUrl": "https://cdn.21st.dev/ephraimduncan/command-menu-04/default/preview.1789690921880-a59459e6-04fc-4f8d-a5be-baa2be9d8a70.png", "installCommand": "npx shadcn@latest add "https://21st.dev/r/ephraimduncan/command-menu-04?api_key=$API_KEY_21ST"", "componentCode": ""use client";

import {
  IconFileText,
  IconFileTypeDocx,
  IconFileTypePdf,
  IconFileTypeXls,
  IconFileZip,
  IconFolder,
  IconMessageCircle,
  IconPhoto,
  IconX,
} from "@tabler/icons-react";
import { Command as CommandPrimitive } from "cmdk";
import { type ComponentType, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Command,
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import { cn } from "@/lib/utils";

export type SearchResultKind = "chat" | "image" | "document" | "project";

export type SearchResult = {
  id: string;
  kind: SearchResultKind;
  title: string;
  /** Shown under the title while searching. Chats use a text excerpt; files use their type. */
  snippet: string;
  date: string;
  /** Images only: CSS background for the thumbnail. */
  thumbnail?: string;
};

type Filter = "all" | SearchResultKind;

const filters: { value: Filter; label: string }[] = [
  { value: "all", label: "All" },
  { value: "chat", label: "Chats" },
  { value: "image", label: "Images" },
  { value: "document", label: "Documents" },
  { value: "project", label: "Projects" },
];

const fileIcons: Record<string, ComponentType<{ className?: string }>> = {
  pdf: IconFileTypePdf,
  docx: IconFileTypeDocx,
  xlsx: IconFileTypeXls,
  zip: IconFileZip,
};

const kindIcons: Record<
  SearchResultKind,
  ComponentType<{ className?: string }>
> = {
  chat: IconMessageCircle,
  image: IconPhoto,
  document: IconFileText,
  project: IconFolder,
};

const lastOpenedChats: SearchResult[] = [
  {
